/**
 * Bundled seal art as data URIs.
 *
 * Generated from app/assets/seals/*.webp so the Worker page can render a
 * stamp without a second request. CSP already allows `img-src data:`.
 * Do not hand-edit; regenerate if the artwork changes.
 */

export const SEAL_IMAGES = {
  bee: "data:image/webp;base64,",
  cat: "data:image/webp;base64,",
  leaf: "data:image/webp;base64,",
  moon: "data:image/webp;base64,",
  mushroom: "data:image/webp;base64,",
  sea: "data:image/webp;base64,",
} as const;

export type StampName = keyof typeof SEAL_IMAGES;
